UPDATE "VGCL" SET text = E'<po>Me etenim de die in diem quærunt,</po>\n<po>et scire vias meas volunt,</po>\n<po>quasi gens quæ justitiam fecerit,</po>\n<po>et judicium Dei sui non dereliquerit.</po>\n<po>Rogant me judicia justitiæ ;</po>\n<po>appropinquare Deo volunt.</po>' WHERE "verseID" = 23116 AND text = E' Me etenim de die in diem quærunt,\n et scire vias meas volunt,\n quasi gens quæ justitiam fecerit,\n et judicium Dei sui non dereliquerit.\n Rogant me judicia justitiæ ;\n appropinquare Deo volunt.\n' AND coalesce(title1, '') = '' AND coalesce(title2, '') = '' AND coalesce(title3, '') = '';  -- Is 58:2
UPDATE "VGCL" SET text = E'<po>Quare jejunavimus, et non aspexisti ;</po>\n<po>humiliavimus animas nostras, et nescisti ?</po>\n<po>Ecce in die jejunii vestri invenitur voluntas vestra,</po>\n<po>et omnes debitores vestros repetitis.</po>' WHERE "verseID" = 23117 AND text = E' Quare jejunavimus, et non aspexisti ;\n humiliavimus animas nostras, et nescisti ?\n Ecce in die jejunii vestri invenitur voluntas vestra,\n et omnes debitores vestros repetitis.\n' AND coalesce(title1, '') = '' AND coalesce(title2, '') = '' AND coalesce(title3, '') = '';  -- Is 58:3
UPDATE "VGCL" SET text = E'<po>Ecce ad lites et contentiones jejunatis,</po>\n<po>et percutitis pugno impie.</po>\n<po>Nolite jejunare sicut usque ad hanc diem,</po>\n<po>ut audiatur in excelso clamor vester.</po>' WHERE "verseID" = 23118 AND text = E' Ecce ad lites et contentiones jejunatis,\n et percutitis pugno impie.\n Nolite jejunare sicut usque ad hanc diem,\n ut audiatur in excelso clamor vester.\n' AND coalesce(title1, '') = '' AND coalesce(title2, '') = '' AND coalesce(title3, '') = '';  -- Is 58:4
