UPDATE "VGCL" SET text = E'<po>et ne forte mollescat cor vestrum,</po>\n<po>et timeatis auditum qui audietur in terra :</po>\n<po>et veniet in anno auditio,</po>\n<po>et post hunc annum auditio,</po>\n<po>et iniquitas in terra,</po>\n<po>et dominator super dominatorem.</po>' WHERE "verseID" = 24585 AND text = E' et ne forte mollescat cor vestrum,\n et timeatis auditum qui audietur in terra :\n et veniet in anno auditio,\n et post hunc annum auditio,\n et iniquitas in terra,\n et dominator super dominatorem.\n' AND coalesce(title1, '') = '' AND coalesce(title2, '') = '' AND coalesce(title3, '') = '';  -- Jr 51:46
