UPDATE "VGCL" SET text = E'<po>Et laudabunt super Babylonem cæli et terra,</po>\n<po>et omnia quæ in eis sunt :</po>\n<po>quia ab aquilone venient ei prædones, ait Dominus.</po>' WHERE "verseID" = 24587 AND text = E' Et laudabunt super Babylonem cæli et terra,\n et omnia quæ in eis sunt :\n quia ab aquilone venient ei prædones, ait Dominus.\n' AND coalesce(title1, '') = '' AND coalesce(title2, '') = '' AND coalesce(title3, '') = '';  -- Jr 51:48
