UPDATE "VGCL" SET text = E'<po>Qui fugistis gladium, venite,</po>\n<po>nolite stare :</po>\n<po>recordamini procul Domini,</po>\n<po>et Jerusalem ascendat super cor vestrum.</po>' WHERE "verseID" = 24589 AND text = E' Qui fugistis gladium, venite,\n nolite stare :\n recordamini procul Domini,\n et Jerusalem ascendat super cor vestrum.\n' AND coalesce(title1, '') = '' AND coalesce(title2, '') = '' AND coalesce(title3, '') = '';  -- Jr 51:50
UPDATE "VGCL" SET text = E'<po>Confusi sumus, quoniam audivimus opprobrium :</po>\n<po>operuit ignominia facies nostras,</po>\n<po>quia venerunt alieni super sanctificationem domus Domini.</po>' WHERE "verseID" = 24590 AND text = E' Confusi sumus, quoniam audivimus opprobrium :\n operuit ignominia facies nostras,\n quia venerunt alieni super sanctificationem domus Domini.\n' AND coalesce(title1, '') = '' AND coalesce(title2, '') = '' AND coalesce(title3, '') = '';  -- Jr 51:51
UPDATE "VGCL" SET text = E'<po>Propterea ecce dies veniunt, ait Dominus,</po>\n<po>et visitabo super sculptilia ejus,</po>\n<po>et in omni terra ejus mugiet vulneratus.</po>' WHERE "verseID" = 24591 AND text = E' Propterea ecce dies veniunt, ait Dominus,\n et visitabo super sculptilia ejus,\n et in omni terra ejus mugiet vulneratus.\n' AND coalesce(title1, '') = '' AND coalesce(title2, '') = '' AND coalesce(title3, '') = '';  -- Jr 51:52
