UPDATE "VGCL" SET text = E'<po>quoniam vastavit Dominus Babylonem,</po>\n<po>et perdidit ex ea vocem magnam :</po>\n<po>et sonabunt fluctus eorum quasi aquæ multæ ;</po>\n<po>dedit sonitum vox eorum :</po>' WHERE "verseID" = 24594 AND text = E' quoniam vastavit Dominus Babylonem,\n et perdidit ex ea vocem magnam :\n et sonabunt fluctus eorum quasi aquæ multæ ;\n dedit sonitum vox eorum :\n' AND coalesce(title1, '') = '' AND coalesce(title2, '') = '' AND coalesce(title3, '') = '';  -- Jr 51:55
UPDATE "VGCL" SET text = E'<po>quia venit super eam, id est super Babylonem, prædo,</po>\n<po>et apprehensi sunt fortes ejus,</po>\n<po>et emarcuit arcus eorum,</po>\n<po>quia fortis ultor Dominus reddens retribuet.</po>' WHERE "verseID" = 24595 AND text = E' quia venit super eam, id est super Babylonem, prædo,\n et apprehensi sunt fortes ejus,\n et emarcuit arcus eorum,\n quia fortis ultor Dominus reddens retribuet.\n' AND coalesce(title1, '') = '' AND coalesce(title2, '') = '' AND coalesce(title3, '') = '';  -- Jr 51:56
UPDATE "VGCL" SET text = E'<po>Et inebriabo principes ejus, et sapientes ejus,</po>\n<po>et duces ejus, et magistratus ejus, et fortes ejus :</po>\n<po>et dormient somnum sempiternum,</po>\n<po>et non expergiscentur, ait Rex</po>\n<po>(Dominus exercituum nomen ejus).</po>' WHERE "verseID" = 24596 AND text = E' Et inebriabo principes ejus, et sapientes ejus,\n et duces ejus, et magistratus ejus, et fortes ejus :\n et dormient somnum sempiternum,\n et non expergiscentur, ait Rex\n (Dominus exercituum nomen ejus).\n' AND coalesce(title1, '') = '' AND coalesce(title2, '') = '' AND coalesce(title3, '') = '';  -- Jr 51:57
UPDATE "VGCL" SET text = E'<po>Hæc dicit Dominus exercituum :</po>\n<po>Murus Babylonis ille latissimus suffossione suffodietur,</po>\n<po>et portæ ejus excelsæ igni comburentur,</po>\n<po>et labores populorum ad nihilum,</po>\n<pol>et gentium in ignem erunt, et disperibunt.</pol>' WHERE "verseID" = 24597 AND text = E' Hæc dicit Dominus exercituum :\n Murus Babylonis ille latissimus suffossione suffodietur,\n et portæ ejus excelsæ igni comburentur,\n et labores populorum ad nihilum,\n et gentium in ignem erunt, et disperibunt.]' AND coalesce(title1, '') = '' AND coalesce(title2, '') = '' AND coalesce(title3, '') = '';  -- Jr 51:58
UPDATE "VGCL" SET text = E'Et factum est, postquam in captivitatem redactus est Israël, et Jerusalem deserta est, sedit Jeremias propheta flens, et planxit lamentatione hac in Jerusalem : et amaro animo suspirans et ejulans, dixit :\n<pof>Quomodo sedet sola</pof>\n<po>civitas plena populo !</po>\n<po>Facta est quasi vidua</po>\n<po>domina gentium ;</po>\n<po>princeps provinciarum</po>\n<po>facta est sub tributo.</po>', title1 = E'Prologus' WHERE "verseID" = 24638 AND text = E' <Prologus>Et factum est, postquam in captivitatem redactus est Israël, et Jerusalem deserta est, sedit Jeremias propheta flens, et planxit lamentatione hac in Jerusalem : et amaro animo suspirans et ejulans, dixit : [<Aleph>Quomodo sedet sola\n civitas plena populo !\n Facta est quasi vidua\n domina gentium ;\n princeps provinciarum\n facta est sub tributo.\n' AND coalesce(title1, '') = '' AND coalesce(title2, '') = '' AND coalesce(title3, '') = '';  -- Lam 1:1
UPDATE "VGCL" SET text = E'<po>Plorans ploravit in nocte,</po>\n<po>et lacrimæ ejus in maxillis ejus :</po>\n<po>non est qui consoletur eam</po>\n<po>ex omnibus caris ejus ;</po>\n<po>omnes amici ejus spreverunt eam,</po>\n<po>et facti sunt ei inimici.</po>', title1 = E'Beth' WHERE "verseID" = 24639 AND text = E' <Beth>Plorans ploravit in nocte,\n et lacrimæ ejus in maxillis ejus :\n non est qui consoletur eam\n ex omnibus caris ejus ;\n omnes amici ejus spreverunt eam,\n et facti sunt ei inimici.\n' AND coalesce(title1, '') = '' AND coalesce(title2, '') = '' AND coalesce(title3, '') = '';  -- Lam 1:2
UPDATE "VGCL" SET text = E'<po>Migravit Judas propter afflictionem,</po>\n<po>et multitudinem servitutis ;</po>\n<po>habitavit inter gentes,</po>\n<po>nec invenit requiem :</po>\n<po>omnes persecutores ejus apprehenderunt eam</po>\n<po>inter angustias.</po>', title1 = E'Ghimel' WHERE "verseID" = 24640 AND text = E' <Ghimel>Migravit Judas propter afflictionem,\n et multitudinem servitutis ;\n habitavit inter gentes,\n nec invenit requiem :\n omnes persecutores ejus apprehenderunt eam\n inter angustias.\n' AND coalesce(title1, '') = '' AND coalesce(title2, '') = '' AND coalesce(title3, '') = '';  -- Lam 1:3
UPDATE "VGCL" SET text = E'<po>Viæ Sion lugent, eo quod non sint</po>\n<po>qui veniant ad solemnitatem :</po>\n<po>omnes portæ ejus destructæ,</po>\n<po>sacerdotes ejus gementes ;</po>\n<po>virgines ejus squalidæ,</po>\n<po>et ipsa oppressa amaritudine.</po>', title1 = E'Daleth' WHERE "verseID" = 24641 AND text = E' <Daleth>Viæ Sion lugent, eo quod non sint\n qui veniant ad solemnitatem :\n omnes portæ ejus destructæ,\n sacerdotes ejus gementes ;\n virgines ejus squalidæ,\n et ipsa oppressa amaritudine.\n' AND coalesce(title1, '') = '' AND coalesce(title2, '') = '' AND coalesce(title3, '') = '';  -- Lam 1:4
UPDATE "VGCL" SET text = E'<po>Facti sunt hostes ejus in capite ;</po>\n<po>inimici ejus locupletati sunt :</po>\n<po>quia Dominus locutus est super eam</po>\n<po>propter multitudinem iniquitatum ejus.</po>\n<po>Parvuli ejus ducti sunt in captivitatem</po>\n<po>ante faciem tribulantis.</po>', title1 = E'He' WHERE "verseID" = 24642 AND text = E' <He>Facti sunt hostes ejus in capite ;\n inimici ejus locupletati sunt :\n quia Dominus locutus est super eam\n propter multitudinem iniquitatum ejus.\n Parvuli ejus ducti sunt in captivitatem\n ante faciem tribulantis.\n' AND coalesce(title1, '') = '' AND coalesce(title2, '') = '' AND coalesce(title3, '') = '';  -- Lam 1:5
UPDATE "VGCL" SET text = E'<po>Et egressus est a filia Sion</po>\n<po>omnis decor ejus ;</po>\n<po>facti sunt principes ejus velut arietes</po>\n<po>non invenientes pascua,</po>\n<po>et abierunt absque fortitudine</po>\n<po>ante faciem subsequentis.</po>', title1 = E'Vau' WHERE "verseID" = 24643 AND text = E' <Vau>Et egressus est a filia Sion\n omnis decor ejus ;\n facti sunt principes ejus velut arietes\n non invenientes pascua,\n et abierunt absque fortitudine\n ante faciem subsequentis.\n' AND coalesce(title1, '') = '' AND coalesce(title2, '') = '' AND coalesce(title3, '') = '';  -- Lam 1:6
UPDATE "VGCL" SET text = E'<po>Recordata est Jerusalem dierum afflictionis suæ,</po>\n<po>et prævaricationis,</po>\n<po>omnium desiderabilium suorum,</po>\n<po>quæ habuerat a diebus antiquis,</po>\n<po>cum caderet populus ejus in manu hostili,</po>\n<po>et non esset auxiliator :</po>\n<po>viderunt eam hostes,</po>\n<po>et deriserunt sabbata ejus.</po>', title1 = E'Zain' WHERE "verseID" = 24644 AND text = E' <Zain>Recordata est Jerusalem dierum afflictionis suæ,\n et prævaricationis,\n omnium desiderabilium suorum,\n quæ habuerat a diebus antiquis,\n cum caderet populus ejus in manu hostili,\n et non esset auxiliator :\n viderunt eam hostes,\n et deriserunt sabbata ejus.\n' AND coalesce(title1, '') = '' AND coalesce(title2, '') = '' AND coalesce(title3, '') = '';  -- Lam 1:7
UPDATE "VGCL" SET text = E'<po>Peccatum peccavit Jerusalem,</po>\n<po>propterea instabilis facta est ;</po>\n<po>omnes qui glorificabant eam spreverunt illam,</po>\n<po>quia viderunt ignominiam ejus :</po>\n<po>ipsa autem gemens</po>\n<po>conversa est retrorsum.</po>', title1 = E'Heth' WHERE "verseID" = 24645 AND text = E' <Heth>Peccatum peccavit Jerusalem,\n propterea instabilis facta est ;\n omnes qui glorificabant eam spreverunt illam,\n quia viderunt ignominiam ejus :\n ipsa autem gemens\n conversa est retrorsum.\n' AND coalesce(title1, '') = '' AND coalesce(title2, '') = '' AND coalesce(title3, '') = '';  -- Lam 1:8
UPDATE "VGCL" SET text = E'<po>Sordes ejus in pedibus ejus,</po>\n<po>nec recordata est finis sui ;</po>\n<po>deposita est vehementer,</po>\n<po>non habens consolatorem.</po>\n<po>Vide, Domine, afflictionem meam,</po>\n<po>quoniam erectus est inimicus.</po>', title1 = E'Teth' WHERE "verseID" = 24646 AND text = E' <Teth>Sordes ejus in pedibus ejus,\n nec recordata est finis sui ;\n deposita est vehementer,\n non habens consolatorem.\n Vide, Domine, afflictionem meam,\n quoniam erectus est inimicus.\n' AND coalesce(title1, '') = '' AND coalesce(title2, '') = '' AND coalesce(title3, '') = '';  -- Lam 1:9
UPDATE "VGCL" SET text = E'<po>Manum suam misit hostis</po>\n<po>ad omnia desiderabilia ejus,</po>\n<po>quia vidit gentes</po>\n<po>ingressas sanctuarium suum,</po>\n<po>de quibus præceperas</po>\n<po>ne intrarent in ecclesiam tuam.</po>', title1 = E'Jod' WHERE "verseID" = 24647 AND text = E' <Jod>Manum suam misit hostis\n ad omnia desiderabilia ejus,\n quia vidit gentes\n ingressas sanctuarium suum,\n de quibus præceperas\n ne intrarent in ecclesiam tuam.\n' AND coalesce(title1, '') = '' AND coalesce(title2, '') = '' AND coalesce(title3, '') = '';  -- Lam 1:10
UPDATE "VGCL" SET text = E'<po>Omnis populus ejus gemens,</po>\n<po>et quærens panem ;</po>\n<po>dederunt pretiosa quæque pro cibo</po>\n<po>ad refocillandam animam.</po>\n<po>Vide, Domine, et considera</po>\n<po>quoniam facta sum vilis !</po>', title1 = E'Caph' WHERE "verseID" = 24648 AND text = E' <Caph>Omnis populus ejus gemens,\n et quærens panem ;\n dederunt pretiosa quæque pro cibo\n ad refocillandam animam.\n Vide, Domine, et considera\n quoniam facta sum vilis !\n' AND coalesce(title1, '') = '' AND coalesce(title2, '') = '' AND coalesce(title3, '') = '';  -- Lam 1:11
UPDATE "VGCL" SET text = E'<po>O vos omnes qui transitis per viam,</po>\n<po>attendite, et videte</po>\n<po>si est dolor sicut dolor meus !</po>\n<po>quoniam vindemiavit me,</po>\n<po>ut locutus est Dominus,</po>\n<po>in die iræ furoris sui.</po>', title1 = E'Lamed' WHERE "verseID" = 24649 AND text = E' <Lamed>O vos omnes qui transitis per viam,\n attendite, et videte\n si est dolor sicut dolor meus !\n quoniam vindemiavit me,\n ut locutus est Dominus,\n in die iræ furoris sui.\n' AND coalesce(title1, '') = '' AND coalesce(title2, '') = '' AND coalesce(title3, '') = '';  -- Lam 1:12
UPDATE "VGCL" SET text = E'<po>De excelso misit ignem in ossibus meis,</po>\n<po>et erudivit me :</po>\n<po>expandit rete pedibus meis,</po>\n<po>convertit me retrorsum ;</po>\n<po>posuit me desolatam,</po>\n<po>tota die mrore confectam.</po>', title1 = E'Mem' WHERE "verseID" = 24650 AND text = E' <Mem>De excelso misit ignem in ossibus meis,\n et erudivit me :\n expandit rete pedibus meis,\n convertit me retrorsum ;\n posuit me desolatam,\n tota die mrore confectam.\n' AND coalesce(title1, '') = '' AND coalesce(title2, '') = '' AND coalesce(title3, '') = '';  -- Lam 1:13
UPDATE "VGCL" SET text = E'<po>Vigilavit jugum iniquitatum mearum ;</po>\n<po>in manu ejus convolutæ sunt,</po>\n<po>et impositæ collo meo.</po>\n<po>Infirmata est virtus mea :</po>\n<po>dedit me Dominus in manu</po>\n<po>de qua non potero surgere.</po>', title1 = E'Nun' WHERE "verseID" = 24651 AND text = E' <Nun>Vigilavit jugum iniquitatum mearum ;\n in manu ejus convolutæ sunt,\n et impositæ collo meo.\n Infirmata est virtus mea :\n dedit me Dominus in manu\n de qua non potero surgere.\n' AND coalesce(title1, '') = '' AND coalesce(title2, '') = '' AND coalesce(title3, '') = '';  -- Lam 1:14
UPDATE "VGCL" SET text = E'<po>Abstulit omnes magnificos meos Dominus</po>\n<po>de medio mei ;</po>\n<po>vocavit adversum me tempus</po>\n<po>ut contereret electos meos.</po>\n<po>Torcular calcavit Dominus</po>\n<po>virgini filiæ Juda.</po>', title1 = E'Samech' WHERE "verseID" = 24652 AND text = E' <Samech>Abstulit omnes magnificos meos Dominus\n de medio mei ;\n vocavit adversum me tempus\n ut contereret electos meos.\n Torcular calcavit Dominus\n virgini filiæ Juda.\n' AND coalesce(title1, '') = '' AND coalesce(title2, '') = '' AND coalesce(title3, '') = '';  -- Lam 1:15
UPDATE "VGCL" SET text = E'<po>Idcirco ego plorans,</po>\n<po>et oculus meus deducens aquas,</po>\n<po>quia longe factus est a me consolator,</po>\n<po>convertens animam meam.</po>\n<po>Facti sunt filii mei perditi,</po>\n<po>quoniam invaluit inimicus.</po>', title1 = E'Ain' WHERE "verseID" = 24653 AND text = E' <Ain>Idcirco ego plorans,\n et oculus meus deducens aquas,\n quia longe factus est a me consolator,\n convertens animam meam.\n Facti sunt filii mei perditi,\n quoniam invaluit inimicus.\n' AND coalesce(title1, '') = '' AND coalesce(title2, '') = '' AND coalesce(title3, '') = '';  -- Lam 1:16
UPDATE "VGCL" SET text = E'<po>Expandit Sion manus suas ;</po>\n<po>non est qui consoletur eam.</po>\n<po>Mandavit Dominus adversum Jacob</po>\n<po>in circuitu ejus hostes ejus ;</po>\n<po>facta est Jerusalem</po>\n<po>quasi polluta menstruis inter eos.</po>', title1 = E'Phe' WHERE "verseID" = 24654 AND text = E' <Phe>Expandit Sion manus suas ;\n non est qui consoletur eam.\n Mandavit Dominus adversum Jacob\n in circuitu ejus hostes ejus ;\n facta est Jerusalem\n quasi polluta menstruis inter eos.\n' AND coalesce(title1, '') = '' AND coalesce(title2, '') = '' AND coalesce(title3, '') = '';  -- Lam 1:17
UPDATE "VGCL" SET text = E'<po>Justus est Dominus,</po>\n<po>quia os ejus ad iracundiam provocavi.</po>\n<po>Audite, obsecro, universi populi,</po>\n<po>et videte dolorem meum :</po>\n<po>virgines meæ et juvenes mei abierunt</po>\n<po>in captivitatem.</po>', title1 = E'Sade' WHERE "verseID" = 24655 AND text = E' <Sade>Justus est Dominus,\n quia os ejus ad iracundiam provocavi.\n Audite, obsecro, universi populi,\n et videte dolorem meum :\n virgines meæ et juvenes mei abierunt\n in captivitatem.\n' AND coalesce(title1, '') = '' AND coalesce(title2, '') = '' AND coalesce(title3, '') = '';  -- Lam 1:18
UPDATE "VGCL" SET text = E'<po>Vocavi amicos meos,</po>\n<po>et ipsi deceperunt me ;</po>\n<po>sacerdotes mei et senes mei</po>\n<po>in urbe consumpti sunt,</po>\n<po>quia quæsierunt cibum sibi</po>\n<po>ut refocillarent animam suam.</po>', title1 = E'Coph' WHERE "verseID" = 24656 AND text = E' <Coph>Vocavi amicos meos,\n et ipsi deceperunt me ;\n sacerdotes mei et senes mei\n in urbe consumpti sunt,\n quia quæsierunt cibum sibi\n ut refocillarent animam suam.\n' AND coalesce(title1, '') = '' AND coalesce(title2, '') = '' AND coalesce(title3, '') = '';  -- Lam 1:19
UPDATE "VGCL" SET text = E'<po>Vide, Domine, quoniam tribulor :</po>\n<po>conturbatus est venter meus,</po>\n<po>subversum est cor meum in memetipsa,</po>\n<po>quoniam amaritudine plena sum.</po>\n<po>Foris interfecit gladius,</po>\n<po>et domi mors similis est.</po>', title1 = E'Res' WHERE "verseID" = 24657 AND text = E' <Res>Vide, Domine, quoniam tribulor :\n conturbatus est venter meus,\n subversum est cor meum in memetipsa,\n quoniam amaritudine plena sum.\n Foris interfecit gladius,\n et domi mors similis est.\n' AND coalesce(title1, '') = '' AND coalesce(title2, '') = '' AND coalesce(title3, '') = '';  -- Lam 1:20
UPDATE "VGCL" SET text = E'<po>Audierunt quia ingemisco ego,</po>\n<po>et non est qui consoletur me ;</po>\n<po>omnes inimici mei audierunt malum meum,</po>\n<po>lætati sunt quoniam tu fecisti :</po>\n<po>adduxisti diem consolationis,</po>\n<po>et fient similes mei.</po>', title1 = E'Sin' WHERE "verseID" = 24658 AND text = E' <Sin>Audierunt quia ingemisco ego,\n et non est qui consoletur me ;\n omnes inimici mei audierunt malum meum,\n lætati sunt quoniam tu fecisti :\n adduxisti diem consolationis,\n et fient similes mei.\n' AND coalesce(title1, '') = '' AND coalesce(title2, '') = '' AND coalesce(title3, '') = '';  -- Lam 1:21
UPDATE "VGCL" SET text = E'<po>Ingrediatur omne malum eorum coram te :</po>\n<po>et vindemia eos, sicut vindemiasti me</po>\n<po>propter omnes iniquitates meas :</po>\n<po>multi enim gemitus mei,</po>\n<pol>et cor meum mrens.</pol>', title1 = E'Thau' WHERE "verseID" = 24659 AND text = E' <Thau>Ingrediatur omne malum eorum coram te :\n et vindemia eos, sicut vindemiasti me\n propter omnes iniquitates meas :\n multi enim gemitus mei,\n et cor meum mrens.]' AND coalesce(title1, '') = '' AND coalesce(title2, '') = '' AND coalesce(title3, '') = '';  -- Lam 1:22
UPDATE "VGCL" SET text = E'<pof>Quomodo obtexit caligine in furore suo</pof>\n<po>Dominus filiam Sion ;</po>\n<po>projecit de cælo in terram</po>\n<po>inclytam Israël,</po>\n<po>et non est recordatus scabelli pedum suorum</po>\n<po>in die furoris sui !</po>', title1 = E'Aleph' WHERE "verseID" = 24660 AND text = E' [<Aleph>Quomodo obtexit caligine in furore suo\n Dominus filiam Sion ;\n projecit de cælo in terram\n inclytam Israël,\n et non est recordatus scabelli pedum suorum\n in die furoris sui !\n' AND coalesce(title1, '') = '' AND coalesce(title2, '') = '' AND coalesce(title3, '') = '';  -- Lam 2:1
UPDATE "VGCL" SET text = E'<po>Præcipitavit Dominus, nec pepercit</po>\n<po>omnia speciosa Jacob :</po>\n<po>destruxit in furore suo</po>\n<po>munitiones virginis Juda,</po>\n<po>et dejecit in terram ;</po>\n<po>polluit regnum et principes ejus.</po>', title1 = E'Beth' WHERE "verseID" = 24661 AND text = E' <Beth>Præcipitavit Dominus, nec pepercit\n omnia speciosa Jacob :\n destruxit in furore suo\n munitiones virginis Juda,\n et dejecit in terram ;\n polluit regnum et principes ejus.\n' AND coalesce(title1, '') = '' AND coalesce(title2, '') = '' AND coalesce(title3, '') = '';  -- Lam 2:2
UPDATE "VGCL" SET text = E'<po>Confregit in ira furoris sui</po>\n<po>omne cornu Israël ;</po>\n<po>avertit retrorsum dexteram suam</po>\n<po>a facie inimici,</po>\n<po>et succendit in Jacob quasi ignem</po>\n<po>flammæ devorantis in gyro.</po>', title1 = E'Ghimel' WHERE "verseID" = 24662 AND text = E' <Ghimel>Confregit in ira furoris sui\n omne cornu Israël ;\n avertit retrorsum dexteram suam\n a facie inimici,\n et succendit in Jacob quasi ignem\n flammæ devorantis in gyro.\n' AND coalesce(title1, '') = '' AND coalesce(title2, '') = '' AND coalesce(title3, '') = '';  -- Lam 2:3
UPDATE "VGCL" SET text = E'<po>Tetendit arcum suum quasi inimicus,</po>\n<po>firmavit dexteram suam quasi hostis,</po>\n<po>et occidit omne quod pulchrum erat visu</po>\n<po>in tabernaculo filiæ Sion ;</po>\n<po>effudit quasi ignem</po>\n<po>indignationem suam.</po>', title1 = E'Daleth' WHERE "verseID" = 24663 AND text = E' <Daleth>Tetendit arcum suum quasi inimicus,\n firmavit dexteram suam quasi hostis,\n et occidit omne quod pulchrum erat visu\n in tabernaculo filiæ Sion ;\n effudit quasi ignem\n indignationem suam.\n' AND coalesce(title1, '') = '' AND coalesce(title2, '') = '' AND coalesce(title3, '') = '';  -- Lam 2:4
UPDATE "VGCL" SET text = E'<po>Factus est Dominus velut inimicus,</po>\n<po>præcipitavit Israël :</po>\n<po>præcipitavit omnia mnia ejus,</po>\n<po>dissipavit munitiones ejus,</po>\n<po>et replevit in filia Juda</po>\n<po>humiliatum et humiliatam.</po>', title1 = E'He' WHERE "verseID" = 24664 AND text = E' <He>Factus est Dominus velut inimicus,\n præcipitavit Israël :\n præcipitavit omnia mnia ejus,\n dissipavit munitiones ejus,\n et replevit in filia Juda\n humiliatum et humiliatam.\n' AND coalesce(title1, '') = '' AND coalesce(title2, '') = '' AND coalesce(title3, '') = '';  -- Lam 2:5
UPDATE "VGCL" SET text = E'<po>Et dissipavit quasi hortum tentorium suum ;</po>\n<po>demolitus est tabernaculum suum.</po>\n<po>Oblivioni tradidit Dominus in Sion</po>\n<po>festivitatem et sabbatum ;</po>\n<po>et in opprobrium, et in indignationem furoris sui,</po>\n<po>regem et sacerdotem.</po>', title1 = E'Vau' WHERE "verseID" = 24665 AND text = E' <Vau>Et dissipavit quasi hortum tentorium suum ;\n demolitus est tabernaculum suum.\n Oblivioni tradidit Dominus in Sion\n festivitatem et sabbatum ;\n et in opprobrium, et in indignationem furoris sui,\n regem et sacerdotem.\n' AND coalesce(title1, '') = '' AND coalesce(title2, '') = '' AND coalesce(title3, '') = '';  -- Lam 2:6
UPDATE "VGCL" SET text = E'<po>Repulit Dominus altare suum ;</po>\n<po>maledixit sanctificationi suæ :</po>\n<po>tradidit in manu inimici</po>\n<po>muros turrium ejus.</po>\n<po>Vocem dederunt in domo Domini</po>\n<po>sicut in die solemni.</po>', title1 = E'Zain' WHERE "verseID" = 24666 AND text = E' <Zain>Repulit Dominus altare suum ;\n maledixit sanctificationi suæ :\n tradidit in manu inimici\n muros turrium ejus.\n Vocem dederunt in domo Domini\n sicut in die solemni.\n' AND coalesce(title1, '') = '' AND coalesce(title2, '') = '' AND coalesce(title3, '') = '';  -- Lam 2:7
UPDATE "VGCL" SET text = E'<po>Cogitavit Dominus dissipare</po>\n<po>murum filiæ Sion ;</po>\n<po>tetendit funiculum suum,</po>\n<po>et non avertit manum suam a perditione :</po>\n<po>luxitque antemurale,</po>\n<po>et murus pariter dissipatus est.</po>', title1 = E'Heth' WHERE "verseID" = 24667 AND text = E' <Heth>Cogitavit Dominus dissipare\n murum filiæ Sion ;\n tetendit funiculum suum,\n et non avertit manum suam a perditione :\n luxitque antemurale,\n et murus pariter dissipatus est.\n' AND coalesce(title1, '') = '' AND coalesce(title2, '') = '' AND coalesce(title3, '') = '';  -- Lam 2:8
UPDATE "VGCL" SET text = E'<po>Defixæ sunt in terra portæ ejus,</po>\n<po>perdidit et contrivit vectes ejus ;</po>\n<po>regem ejus et principes ejus in gentibus :</po>\n<po>non est lex,</po>\n<po>et prophetæ ejus non invenerunt</po>\n<po>visionem a Domino.</po>', title1 = E'Teth' WHERE "verseID" = 24668 AND text = E' <Teth>Defixæ sunt in terra portæ ejus,\n perdidit et contrivit vectes ejus ;\n regem ejus et principes ejus in gentibus :\n non est lex,\n et prophetæ ejus non invenerunt\n visionem a Domino.\n' AND coalesce(title1, '') = '' AND coalesce(title2, '') = '' AND coalesce(title3, '') = '';  -- Lam 2:9
UPDATE "VGCL" SET text = E'<po>Sederunt in terra, conticuerunt</po>\n<po>senes filiæ Sion ;</po>\n<po>consperserunt cinere capita sua,</po>\n<po>accincti sunt ciliciis :</po>\n<po>abjecerunt in terram capita sua</po>\n<po>virgines Jerusalem.</po>', title1 = E'Jod' WHERE "verseID" = 24669 AND text = E' <Jod>Sederunt in terra, conticuerunt\n senes filiæ Sion ;\n consperserunt cinere capita sua,\n accincti sunt ciliciis :\n abjecerunt in terram capita sua\n virgines Jerusalem.\n' AND coalesce(title1, '') = '' AND coalesce(title2, '') = '' AND coalesce(title3, '') = '';  -- Lam 2:10
UPDATE "VGCL" SET text = E'<po>Defecerunt præ lacrimis oculi mei,</po>\n<po>conturbata sunt viscera mea ;</po>\n<po>effusum est in terra jecur meum</po>\n<po>super contritione filiæ populi mei,</po>\n<po>cum deficeret parvulus et lactens</po>\n<po>in plateis oppidi.</po>', title1 = E'Caph' WHERE "verseID" = 24670 AND text = E' <Caph>Defecerunt præ lacrimis oculi mei,\n conturbata sunt viscera mea ;\n effusum est in terra jecur meum\n super contritione filiæ populi mei,\n cum deficeret parvulus et lactens\n in plateis oppidi.\n' AND coalesce(title1, '') = '' AND coalesce(title2, '') = '' AND coalesce(title3, '') = '';  -- Lam 2:11
UPDATE "VGCL" SET text = E'<po>Matribus suis dixerunt :</po>\n<po>Ubi est triticum et vinum ?</po>\n<po>cum deficerent quasi vulnerati</po>\n<po>in plateis civitatis,</po>\n<po>cum exhalarent animas suas</po>\n<po>in sinu matrum suarum.</po>', title1 = E'Lamed' WHERE "verseID" = 24671 AND text = E' <Lamed>Matribus suis dixerunt :\n Ubi est triticum et vinum ?\n cum deficerent quasi vulnerati\n in plateis civitatis,\n cum exhalarent animas suas\n in sinu matrum suarum.\n' AND coalesce(title1, '') = '' AND coalesce(title2, '') = '' AND coalesce(title3, '') = '';  -- Lam 2:12
UPDATE "VGCL" SET text = E'<po>Cui comparabo te, vel cui assimilabo te,</po>\n<po>filia Jerusalem ?</po>\n<po>cui exæquabo te, et consolabor te,</po>\n<po>virgo, filia Sion ?</po>\n<po>magna est enim velut mare contritio tua :</po>\n<po>quis medebitur tui ?</po>', title1 = E'Mem' WHERE "verseID" = 24672 AND text = E' <Mem>Cui comparabo te, vel cui assimilabo te,\n filia Jerusalem ?\n cui exæquabo te, et consolabor te,\n virgo, filia Sion ?\n magna est enim velut mare contritio tua :\n quis medebitur tui ?\n' AND coalesce(title1, '') = '' AND coalesce(title2, '') = '' AND coalesce(title3, '') = '';  -- Lam 2:13
UPDATE "VGCL" SET text = E'<po>Prophetæ tui viderunt tibi</po>\n<po>falsa et stulta ;</po>\n<po>nec aperiebant iniquitatem tuam,</po>\n<po>ut te ad pnitentiam provocarent ;</po>\n<po>viderunt autem tibi assumptiones falsas,</po>\n<po>et ejectiones.</po>', title1 = E'Nun' WHERE "verseID" = 24673 AND text = E' <Nun>Prophetæ tui viderunt tibi\n falsa et stulta ;\n nec aperiebant iniquitatem tuam,\n ut te ad pnitentiam provocarent ;\n viderunt autem tibi assumptiones falsas,\n et ejectiones.\n' AND coalesce(title1, '') = '' AND coalesce(title2, '') = '' AND coalesce(title3, '') = '';  -- Lam 2:14
UPDATE "VGCL" SET text = E'<po>Plauserunt super te manibus</po>\n<po>omnes transeuntes per viam ;</po>\n<po>sibilaverunt et moverunt caput suum</po>\n<po>super filiam Jerusalem :</po>\n<po>Hæccine est urbs, dicentes, perfecti decoris,</po>\n<po>gaudium universæ terræ ?</po>', title1 = E'Samech' WHERE "verseID" = 24674 AND text = E' <Samech>Plauserunt super te manibus\n omnes transeuntes per viam ;\n sibilaverunt et moverunt caput suum\n super filiam Jerusalem :\n Hæccine est urbs, dicentes, perfecti decoris,\n gaudium universæ terræ ?\n' AND coalesce(title1, '') = '' AND coalesce(title2, '') = '' AND coalesce(title3, '') = '';  -- Lam 2:15
UPDATE "VGCL" SET text = E'<po>Aperuerunt super te os suum</po>\n<po>omnes inimici tui :</po>\n<po>sibilaverunt, et fremuerunt dentibus,</po>\n<po>et dixerunt : Devorabimus :</po>\n<po>en ista est dies quam exspectabamus ;</po>\n<po>invenimus, vidimus.</po>', title1 = E'Phe' WHERE "verseID" = 24675 AND text = E' <Phe>Aperuerunt super te os suum\n omnes inimici tui :\n sibilaverunt, et fremuerunt dentibus,\n et dixerunt : Devorabimus :\n en ista est dies quam exspectabamus ;\n invenimus, vidimus.\n' AND coalesce(title1, '') = '' AND coalesce(title2, '') = '' AND coalesce(title3, '') = '';  -- Lam 2:16
UPDATE "VGCL" SET text = E'<po>Fecit Dominus quæ cogitavit ;</po>\n<po>complevit sermonem suum,</po>\n<po>quem præceperat a diebus antiquis :</po>\n<po>destruxit, et non pepercit,</po>\n<po>et lætificavit super te inimicum,</po>\n<po>et exaltavit cornu hostium tuorum.</po>', title1 = E'Ain' WHERE "verseID" = 24676 AND text = E' <Ain>Fecit Dominus quæ cogitavit ;\n complevit sermonem suum,\n quem præceperat a diebus antiquis :\n destruxit, et non pepercit,\n et lætificavit super te inimicum,\n et exaltavit cornu hostium tuorum.\n' AND coalesce(title1, '') = '' AND coalesce(title2, '') = '' AND coalesce(title3, '') = '';  -- Lam 2:17
UPDATE "VGCL" SET text = E'<po>Clamavit cor eorum ad Dominum</po>\n<po>super muros filiæ Sion :</po>\n<po>Deduc quasi torrentem lacrimas</po>\n<po>per diem et noctem ;</po>\n<po>non des requiem tibi,</po>\n<po>neque taceat pupilla oculi tui.</po>', title1 = E'Sade' WHERE "verseID" = 24677 AND text = E' <Sade>Clamavit cor eorum ad Dominum\n super muros filiæ Sion :\n Deduc quasi torrentem lacrimas\n per diem et noctem ;\n non des requiem tibi,\n neque taceat pupilla oculi tui.\n' AND coalesce(title1, '') = '' AND coalesce(title2, '') = '' AND coalesce(title3, '') = '';  -- Lam 2:18
UPDATE "VGCL" SET text = E'<po>Consurge, lauda in nocte,</po>\n<po>in principio vigiliarum ;</po>\n<po>effunde sicut aquam cor tuum</po>\n<po>ante conspectum Domini :</po>\n<po>leva ad eum manus tuas</po>\n<po>pro anima parvulorum tuorum,</po>\n<po>qui defecerunt in fame</po>\n<po>in capite omnium compitorum.</po>', title1 = E'Coph' WHERE "verseID" = 24678 AND text = E' <Coph>Consurge, lauda in nocte,\n in principio vigiliarum ;\n effunde sicut aquam cor tuum\n ante conspectum Domini :\n leva ad eum manus tuas\n pro anima parvulorum tuorum,\n qui defecerunt in fame\n in capite omnium compitorum.\n' AND coalesce(title1, '') = '' AND coalesce(title2, '') = '' AND coalesce(title3, '') = '';  -- Lam 2:19
UPDATE "VGCL" SET text = E'<po>Vide, Domine, et considera</po>\n<po>quem vindemiaveris ita.</po>\n<po>Ergone comedent mulieres fructum suum,</po>\n<po>parvulos ad mensuram palmæ ?</po>\n<po>si occiditur in sanctuario Domini</po>\n<po>sacerdos et propheta ?</po>', title1 = E'Res' WHERE "verseID" = 24679 AND text = E' <Res>Vide, Domine, et considera\n quem vindemiaveris ita.\n Ergone comedent mulieres fructum suum,\n parvulos ad mensuram palmæ ?\n si occiditur in sanctuario Domini\n sacerdos et propheta ?\n' AND coalesce(title1, '') = '' AND coalesce(title2, '') = '' AND coalesce(title3, '') = '';  -- Lam 2:20
UPDATE "VGCL" SET text = E'<po>Jacuerunt in terra foris</po>\n<po>puer et senex ;</po>\n<po>virgines meæ et juvenes mei</po>\n<po>ceciderunt in gladio :</po>\n<po>interfecisti in die furoris tui,</po>\n<po>percussisti, nec misertus es.</po>', title1 = E'Sin' WHERE "verseID" = 24680 AND text = E' <Sin>Jacuerunt in terra foris\n puer et senex ;\n virgines meæ et juvenes mei\n ceciderunt in gladio :\n interfecisti in die furoris tui,\n percussisti, nec misertus es.\n' AND coalesce(title1, '') = '' AND coalesce(title2, '') = '' AND coalesce(title3, '') = '';  -- Lam 2:21
